import javax.inject.Inject

class LegalRepositoryImpl @Inject constructor(
    @ApplicationContext private val context: Context
) : LegalRepository {

    override val acceptedVersion: Flow<Int> = context.legalDataStore.data.map { prefs ->
        prefs[LegalPreferences.ACCEPTED_VERSION] ?: 0
